import numpy as np
L=open('opt.xyz').read().split('\n')[2:];L=[l.split() for l in L if l]
P=np.array([[float(x) for x in l[1:]] for l in L])
for i in range(1,50):
  r=np.linalg.norm(P[i]-P[0])
  if r<2.6: print(i,L[i][0],round(r,2))
C1,C2,M1,M2=P[38],P[39],P[40],P[41]
def dih(a,b,c,d):
  b0=a-b;b1=c-b;b2=d-c;b1/=np.linalg.norm(b1);v=b0-b0@b1*b1;w=b2-b2@b1*b1
  return np.degrees(np.arctan2(np.cross(b1,v)@w,v@w))
print('Cr-C1=C2-Me',dih(P[0],C1,C2,M2),'C1-C2',np.linalg.norm(C1-C2))
